package io.github.achaii.moonbridge

import android.graphics.Bitmap
import android.graphics.BitmapFactory
import android.util.Base64

/**
 * 耳机头图。
 * 宿主进程（com.heytap.mydevices）里读不到模块自己的 assets/，
 * 所以图片直接内嵌成 base64 带进代码，不依赖任何资源路径。
 */
internal object IconAsset {
    private const val P0 = ""
    private const val P1 = ""
    private const val P2 = ""
    private const val P3 = ""

    private val B64: String by lazy { P0 + P1 + P2 + P3 }

    @Volatile
    private var cache: Bitmap? = null

    fun bitmap(): Bitmap? {
        cache?.let { return it }
        return try {
            val raw = Base64.decode(B64, Base64.NO_WRAP)
            val bmp = BitmapFactory.decodeByteArray(raw, 0, raw.size)
            cache = bmp
            bmp
        } catch (t: Throwable) {
            null
        }
    }
}
